const items = $input.all();
const returnItems = [];

// Verificar si hay items
if (!items || items.length === 0) {
  return [];
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json || !item.json.start || !item.json.start.dateTime) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let data = item.json;

  const dia = data.start.dateTime.split('T')[0];
  const inicio = data.start.dateTime.split('T')[1].substring(0, 5);
  const final = data.end.dateTime.split('T')[1].substring(0, 5);

  returnItems.push({
    json: {
      dia: dia,
      inicio: inicio, 
      final: final
    }
  });
}

return returnItems;

function calcularTurnosDisponibles() {
  const tiempoData = $('When Executed by Another Workflow').first().json;
  let tiempoMantenimiento = 60; // Solo como fallback si no se puede obtener datos

  // Manejar diferentes formatos de entrada
  if (tiempoData && tiempoData.query) {
    if (typeof tiempoData.query === 'string') {
      // Formato directo "01:30:00"
      if (tiempoData.query.includes(':')) {
        const [hours, minutes] = tiempoData.query.split(':').map(Number);
        tiempoMantenimiento = (hours * 60) + minutes;
      } else {
        // Formato directo número como string "90"
        tiempoMantenimiento = parseInt(tiempoData.query);
      }
    } else {
      // Formato JSON anidado
      try {
        const parsedQuery = JSON.parse(tiempoData.query);
        if (parsedQuery.tiempo) {
          if (parsedQuery.tiempo.includes(':')) {
            const [hours, minutes] = parsedQuery.tiempo.split(':').map(Number);
            tiempoMantenimiento = (hours * 60) + minutes;
          } else {
            tiempoMantenimiento = parseInt(parsedQuery.tiempo);
          }
        }
      } catch (e) {
        // Si falla el parsing, usar fallback de 30 min
        tiempoMantenimiento = 30;
      }
    }
  } else if (tiempoData && tiempoData.tiempo) {
    tiempoMantenimiento = tiempoData.tiempo;
  }

  const feriadosData = $('feriados').first().json.feriadosEncontrados || [];
  const tallerData = $('Get row(s) in sheet').first().json;
  const turnosOcupadosRaw = $('Code').all();

  const turnosOcupados = [];
  turnosOcupadosRaw.forEach(item => {
    if (item.json && Array.isArray(item.json)) {
      turnosOcupados.push(...item.json);
    } else if (item.json && item.json.dia) {
      turnosOcupados.push(item.json);
    }
  });

  // CAMBIO PRINCIPAL: Usar solo el tiempo de mantenimiento, sin sumar otros tiempos
  const tiempoTotal = tiempoMantenimiento;

  function timeToMinutes(timeStr) {
    const [hours, minutes] = timeStr.split(':').map(Number);
    return hours * 60 + minutes;
  }

  function minutesToTime(minutes) {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
  }

  // AGREGADO: Función para obtener día de la semana
  function getDayOfWeek(dateStr) {
    const days = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
    const date = new Date(dateStr + 'T00:00:00');
    return days[date.getUTCDay()];
  }

  const apertura = timeToMinutes(tallerData.Apertura);
  const cierre = timeToMinutes(tallerData.Cierre);
  const inicioAlmuerzo = timeToMinutes(tallerData['Inicio Almuerzo']);
  const finAlmuerzo = timeToMinutes(tallerData['Fin Almuerzo']);
  const inicioDesayuno = timeToMinutes(tallerData['Inicio Desayuno']);
  const finDesayuno = timeToMinutes(tallerData['Fin Desayuno']);

  const fechasHorariosOcupados = new Set();
  turnosOcupados.forEach(turno => {
    if (turno.dia && turno.inicio && turno.final) {
      const inicioOcupado = timeToMinutes(turno.inicio);
      const finOcupado = timeToMinutes(turno.final);

      for (let minuto = inicioOcupado; minuto < finOcupado; minuto += 15) {
        const key = `${turno.dia}_${minutesToTime(minuto)}`;
        fechasHorariosOcupados.add(key);
      }
    }
  });

  const feriados = new Set(feriadosData);
  const turnosDisponibles = [];
  const hoy = new Date();
  let diasBuscados = 0;
  const maxDias = 60;

  let fechaActual = new Date(hoy);
  fechaActual.setDate(fechaActual.getDate() + 2);

  while (turnosDisponibles.length < 6 && diasBuscados < maxDias) {
    const fechaStr = fechaActual.toISOString().split('T')[0];
    const diaSemana = fechaActual.getDay();

    if (diaSemana >= 1 && diaSemana <= 5 && !feriados.has(fechaStr)) {
      const turnosDia = [];

      function estaDisponible(horaInicio, duracion) {
        const horaFin = horaInicio + duracion;

        if (horaInicio < finAlmuerzo && horaFin > inicioAlmuerzo) {
          return false;
        }

        if (horaInicio < finDesayuno && horaFin > inicioDesayuno) {
          return false;
        }

        for (let minuto = horaInicio; minuto < horaFin; minuto += 15) {
          const key = `${fechaStr}_${minutesToTime(minuto)}`;
          if (fechasHorariosOcupados.has(key)) {
            return false;
          }
        }

        return true;
      }

      // MODIFICADO: Agregar fechaFormato al crear turnos
      const dayName = getDayOfWeek(fechaStr);
      const [year, month, day] = fechaStr.split('-');

      for (let horaActual = apertura; horaActual + tiempoTotal <= cierre; horaActual += 15) {
        if (estaDisponible(horaActual, tiempoTotal)) {
          turnosDia.push({
            dia: fechaStr,
            inicio: minutesToTime(horaActual),
            final: minutesToTime(horaActual + tiempoTotal),

            // ✅ FORMATO PEDIDO
            fechaFormato: `${dayName} ${parseInt(day)}/${parseInt(month)}/${year}`,

            Id_Calendario: tallerData.Id_Calendario
          });
        }
      }

      turnosDisponibles.push(...turnosDia.slice(0, 2));
    }

    fechaActual.setDate(fechaActual.getDate() + 1);
    diasBuscados++;
  }

  turnosDisponibles.sort((a, b) => {
    if (a.dia !== b.dia) {
      return new Date(a.dia) - new Date(b.dia);
    }
    return a.inicio.localeCompare(b.inicio);
  });

  return {
    turnosDisponibles: turnosDisponibles.slice(0, 6),
    tiempoMantenimientoCalculado: tiempoMantenimiento
  };
}

const resultado = calcularTurnosDisponibles();

return [{
  json: {
    turnosDisponibles: resultado.turnosDisponibles,
    tiempoTotalCalculado: resultado.tiempoMantenimientoCalculado,
    cantidadTurnos: resultado.turnosDisponibles.length
  }
}];

function obtenerFeriados() {
  // Obtener los feriados del nodo anterior
  const feriadosData = $input.all(); // Obtiene todos los items del nodo anterior
  const feriados = [];

  // Extraer las fechas de los feriados del formato que recibes
  feriadosData.forEach(item => {
    if (item.json && item.json.start && item.json.start.date) {
      feriados.push(item.json.start.date);
    }
    // Si el feriado dura más de un día, también agregar las fechas intermedias
    if (item.json && item.json.end && item.json.end.date && item.json.start.date !== item.json.end.date) {
      const fechaInicio = new Date(item.json.start.date);
      const fechaFin = new Date(item.json.end.date);

      // Agregar todas las fechas entre inicio y fin
      const fechaActual = new Date(fechaInicio);
      while (fechaActual < fechaFin) {
        feriados.push(fechaActual.toISOString().split('T')[0]);
        fechaActual.setDate(fechaActual.getDate() + 1);
      }
    }
  });

  // Eliminar duplicados de la lista de feriados
  const feriadosUnicos = [...new Set(feriados)];

  return feriadosUnicos;
}

const feriadosEncontrados = obtenerFeriados();

return [{
  json: {
    feriadosEncontrados: feriadosEncontrados
  }
}];
